verify.cmd:
node -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const norm=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")
const rd=(f)=>{try{return norm(fs.readFileSync(f,"utf8"))}catch(e){return null}}
const co=rd("lib/commerce/checkout.ts")
if(co===null)process.exit(79)
const sr=rd("lib/commerce/split-refund.ts")
if(sr===null||!/export function proportionRefund\(/.test(sr))fail("nothing proportions a refund across the sellers of a split order, so a refund would come from one seller or none")
if(!/createReversal\(/.test(sr))fail("nothing reverses a transfer, so a refunded buyer is made whole from the platform and the sellers keep the money")
if(!/idempotencyKey:\s*reversalIdempotencyKey\(/.test(sr))fail("a reversal is not made under a key fixed to its row and the refund, so a replayed refund can take a seller share twice")
if(!/transfers\.retrieve\(/.test(sr))fail("a reversal is sized from this ledger instead of what Stripe says is already reversed, so a lost write or a dashboard reversal is taken back twice")
const migs=fs.readdirSync("supabase/migrations").filter((f)=>f.endsWith(".sql")).sort().map((f)=>fs.readFileSync("supabase/migrations/"+f,"utf8").replace(/^\s*--.*$/gm," ")).join("\n")
if(!/add column if not exists refund_reversal_cents/.test(migs)||!/commerce_order_transfers_status_check\s+check \(status in \([^)]*.cancelled./.test(migs))fail("the ledger cannot record what a refund owes back or a transfer cancelled before it was made, so a failed reversal is forgotten and an unpaid share of a refunded order stays open")
const rf=co.slice(co.indexOf("export async function refundCommerceOrder("),co.indexOf("export interface CommerceRefundOptions"))
if(!/funds_flow === .separate.[\s\S]*reverseSplitTransfers\(/.test(rf))fail("refundCommerceOrder does not reverse the transfers of a separate order, so its sellers keep the money the buyer got back")
if(!/reverseSplitRefundForPaymentIntent\(/.test(co))fail("a refund made in the Stripe dashboard (charge.refunded) reverses no seller transfer")
if(!/charge\.dispute\.closed/.test(rd("app/api/webhooks/stripe/route.ts")||""))fail("a lost dispute is acked and forgotten, so money already in a seller balance stays there while the platform pays the chargeback")
if(!/reconcileSplitReversals\(/.test(rd("app/api/cron/reconcile-transfers/route.ts")||""))fail("a reversal that failed is never retried, so a seller keeps a refunded share until a person notices")
console.log("ok")'
